;(function(){
  // ── Préférences cartes : mise en avant (or) & griser les vides ──────
  var _sc = localStorage.getItem('wiki-show-complete');
  var _de = localStorage.getItem('wiki-dim-empty');
  var wcShowComplete = _sc !== null ? _sc === '1' : true;
  var wcDimEmpty    = _de !== null ? _de === '1' : true;

  function applyCardPrefs() {
    document.body.classList.toggle('wc-no-complete', !wcShowComplete);
    document.body.classList.toggle('wc-no-dim-empty', !wcDimEmpty);
  }
  applyCardPrefs();

  var btnC = document.getElementById('wiki-complete-toggle');
  var btnE = document.getElementById('wiki-empty-toggle');

  function syncBtnC() { if (btnC) btnC.classList.toggle('active', wcShowComplete); }
  function syncBtnE() { if (btnE) btnE.classList.toggle('active', wcDimEmpty); }
  syncBtnC(); syncBtnE();

  if (btnC) btnC.addEventListener('click', function() {
    wcShowComplete = !wcShowComplete;
    localStorage.setItem('wiki-show-complete', wcShowComplete ? '1' : '0');
    syncBtnC(); applyCardPrefs();
  });
  if (btnE) btnE.addEventListener('click', function() {
    wcDimEmpty = !wcDimEmpty;
    localStorage.setItem('wiki-dim-empty', wcDimEmpty ? '1' : '0');
    syncBtnE(); applyCardPrefs();
  });
})();
